if(PHP_SAPI!=='cli'||!in_array('--confirmar',$argv,true))exit("Uso: php db/migrar_ajustes_planilla.php --confirmar\n");require_once __DIR__.'/../config/conexion.php';if(!$conexion->query("SHOW TABLES LIKE 'planilla_ajustes'")->fetch()){$conexion->exec("CREATE TABLE planilla_ajustes(id_ajuste BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_planilla_detalle BIGINT UNSIGNED NOT NULL,id_detalle_concepto BIGINT UNSIGNED NULL,naturaleza ENUM('BONIFICACION','DESCUENTO') NOT NULL,importe DECIMAL(12,2) NOT NULL,motivo VARCHAR(250) NOT NULL,registrado_por BIGINT UNSIGNED NULL,registrado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,estado ENUM('ACTIVO','ANULADO') NOT NULL DEFAULT 'ACTIVO',anulado_por BIGINT UNSIGNED NULL,anulado_en DATETIME NULL,motivo_anulacion VARCHAR(250) NULL,KEY ix_ajuste_detalle(id_planilla_detalle,estado),CONSTRAINT fk_ajuste_planilla_detalle FOREIGN KEY(id_planilla_detalle) REFERENCES planilla_detalles(id_planilla_detalle),CONSTRAINT fk_ajuste_concepto FOREIGN KEY(id_detalle_concepto) REFERENCES planilla_detalle_conceptos(id_detalle_concepto) ON DELETE SET NULL) ENGINE=InnoDB");echo "Ajustes manuales de planilla creados.\n";}$regla=$conexion->query("SELECT DELETE_RULE FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='planilla_ajustes' AND CONSTRAINT_NAME='fk_ajuste_concepto'")->fetchColumn();if($regla&&$regla!=='SET NULL'){$conexion->exec("ALTER TABLE planilla_ajustes DROP FOREIGN KEY fk_ajuste_concepto,ADD CONSTRAINT fk_ajuste_concepto FOREIGN KEY(id_detalle_concepto) REFERENCES planilla_detalle_conceptos(id_detalle_concepto) ON DELETE SET NULL");echo "Anulacion segura habilitada.\n";}
